import { findRing } from "@/utils/xgraph-util";
import { Graph, GraphData, IEdge, INode, NodeConfig } from "@antv/g6";
import _ from "lodash";

interface NodeData {
  nodeType: string;
  nodeName?: string;
  relationList?: Array<{
    id: string;
    name: string;
  }>;
}

interface CFG {
  illicitRingType?: Array<string>;
}

type ErrorData =
  | Array<{
      type: string;
      value: string;
    }>
  | undefined;

const concatErrorData = <T>(arr: Array<T> | undefined, newV: T) => {
  return [newV];
};

/**
 * @description 对 relation 字段进行强制准确化
 */
export const nodeRelationCheck = (node: INode) => {
  const nodeModel = node.getModel();
  const nodeData = nodeModel.nodeData as NodeData;
  const relationList = nodeData.relationList || [];
};
/**
 * @description 验证通过返回空
 * 不通过，返回 true
 */

const validateNodeErrorFn = (nodeData: NodeData) => {
  const relationList = nodeData.relationList || [];
  const nodeType = nodeData.nodeType;
  if (["Switch", "BranchOptions"].includes(nodeType)) {
    if (relationList.length === 0) {
      return true;
    }

    if (relationList.length > 0) {
      if (relationList.find((v) => v.name === "")) {
        return true;
      }
    }
  }
};

/**
 * @description 只验证某个节点的数据
 */
export const validateNode = (node: INode) => {
  node.setState("error", false);
  const nodeModel = node.getModel();
  const nodeData = nodeModel.nodeData as NodeData;
  const errorData = (nodeModel.errorData || []) as ErrorData;
  if (validateNodeErrorFn(nodeData)) {
    node.setState("error", true);
    node.update({
      errorData: concatErrorData(errorData, {
        type: "dataError",
        value: "节点数据填写不正确",
      }),
    });
  }
};

const validateNodeData = async (xGraph: Graph) => {
  const graphNodes = xGraph.getNodes() || [];
  for (const node of graphNodes) {
    const nodeModel = node.getModel();
    const nodeData = nodeModel.nodeData as NodeData;
    const errorData = (nodeModel.errorData || []) as ErrorData;
    if (validateNodeErrorFn(nodeData)) {
      node.setState("error", true);
      node.update({
        errorData: concatErrorData(errorData, {
          type: "dataError",
          value: "节点数据填写不正确",
        }),
      });
    }
  }
};

const validateRingList = async (xGraph: Graph, cfg: CFG) => {
  const illicitRingType = cfg.illicitRingType || [];

  if (illicitRingType.length > 0) {
    const xGraphData = xGraph.save();
    const ringList = findRing(xGraphData as GraphData);

    const graphNodes = xGraph.getNodes() || [];
    const graphEdges = xGraph.getEdges() || [];

    ringList.forEach((v) => {
      const { nodes, edges } = v;
      const nodeIds = nodes.map((v) => v.id);
      const isError = nodes.every((v) => {
        const type = _.get(v, "nodeData.nodeType", "");
        return illicitRingType.includes(type);
      });
      if (isError) {
        const errorGraphNodes = graphNodes.filter((v) => {
          return nodeIds.includes(v.get("id"));
        });

        errorGraphNodes.forEach((node) => {
          const nodeModel = node.getModel();
          const errorData = (nodeModel.errorData || []) as ErrorData;
          node.setState("error", true);
          node.update({
            errorData: concatErrorData(errorData, {
              type: "ringError",
              value: "节点存在回环，不允许自动节点回环",
            }),
          });
        });

        const edgeIds = edges.map((v) => v.id);
        const errorGraphEdges = graphEdges.filter((v) => {
          return edgeIds.includes(v.get("id"));
        });

        errorGraphEdges.forEach((edge) => {
          edge.setState("error", true);
        });
      }
    });
  }
};

/**
 * @description 验证节点在开始节点的树中
 */
const validateNodeIsInTree = async (xGraph: Graph) => {
  const graphNodes = xGraph.getNodes() || [];
  const graphEdges = xGraph.getEdges() || [];

  const startNode = xGraph.find("node", (v) => {
    return v.getModel()["type"] === "start-node";
  });

  const allEdges: any[] = [];
  const allNodes: any[] = [];
  let nodes = [startNode];
  let edgesArr = [];

  // 最大 2000 层 嵌套子元素，再大计算可能会很久。放弃计算。
  for (let i = 0; i < 2000; i++) {
    for (const node of nodes) {
      if (allNodes.includes(node)) continue;
      allNodes.push(node);
      if (node && node.get("type") === "node") {
        const cEdges = (node as INode).getOutEdges();
        edgesArr.push(cEdges);
      }
    }
    if (edgesArr.length === 0) break;

    nodes = [];
    for (const edges of edgesArr) {
      for (const edge of edges) {
        if (allEdges.includes(edge)) continue;
        allEdges.push(edge);
        nodes.push(edge.getTarget());
      }
    }
    edgesArr = [];
    if (nodes.length === 0) break;
  }

  const diffNodes = graphNodes.filter((node) => {
    return !allNodes.includes(node);
  });
  const diffEdges = graphEdges.filter((node) => {
    return !allEdges.includes(node);
  });

  diffNodes.forEach((node) => {
    node.setState("error", true);
    const nodeModel = node.getModel();
    const errorData = (nodeModel.errorData || []) as ErrorData;
    node.update({
      errorData: concatErrorData(errorData, {
        type: "inTreeError",
        value: "节点没有连接入主路",
      }),
    });
  });

  diffEdges.forEach((edge) => {
    edge.setState("error", true);
  });
};

export const validateXGraph = async (xGraph: Graph, cfg: CFG) => {
  console.log("========= 执行一次全画板验证 ==========");

  const graphNodes = xGraph.getNodes() || [];
  const graphEdges = xGraph.getEdges() || [];

  graphNodes.forEach((node) => {
    node.setState("error", false);
    node.update({
      errorData: [],
    });
  });
  graphEdges.forEach((node) => {
    node.setState("error", false);
  });

  await validateNodeData(xGraph);
  await validateRingList(xGraph, cfg);

  await validateNodeIsInTree(xGraph);
  console.log("========== 全画板验证完成 =========");
};
