<template>
  <div id="qa-tree-container" class="qa-tree-container">
    <nodes-preview :node-list="nodeList" />
    <canvas-zoom :graph="xGraph" />
    <div id="qa-tree-g6" ref="painter"></div>
    <div class="layout-button">
      <!-- <button class="button" @click="toggleEdgeType">🎡</button> -->
      <button class="button" @click="centerGraph">🔲</button>
      <button class="button" @click="handleClickLayout(true)">🗂️</button>
      <button class="button" @click="handlerSave">🗄️</button>
    </div>
    <edit-node-component
      ref="editNode"
      @submit="handlerEditNodeSubmit"
      @close="handlerEditNodeDialogClose"
    ></edit-node-component>
  </div>
</template>

<script>
import _ from "lodash";
import G6 from "@antv/g6";
import { getEdgeDefineCfg } from "./flow-util/edge/edge.js";
// import { GraphLayoutPredict } from "@antv/vis-predict-engine";
import { getCustomNodeCfg } from "./flow-util/node/customNode.js";
import { getStartNodeCfg } from "./flow-util/node/startNode.js";

import {
  getDragCreateEdgeOpt,
  buttonClick,
  getClickCreateEdgeOpt,
  getDragCreateNodeOpt,
  nodeClick,
  getDeleteEdgeOpt,
} from "./flow-util/behavior/index.js";
// DESC: shallowRef 非常重要，因为 g6 无法共享 proxy 构造出来的数据
import { shallowRef } from "vue";
import { g6Config } from "./flow-util/config.ts";
import { getNodeUUID } from "@/utils";
import {
  validateNode,
  validateXGraph,
  nodeRelationCheck,
} from "./validateXGraph.ts";

export default {
  name: "QaTree",

  components: {},

  // mixins: [mixins],
  props: {
    gConfig: {
      type: Object,
      default: () => ({}),
    },
    qaTreeDisabled: {
      type: Boolean,
      default: false,
    },
    initJson: {
      type: String,
      default: "",
    },
  },
  graphNodes: [],
  graphEdges: [],
  setup() {
    const xGraph = shallowRef(null);
    return { xGraph: xGraph };
  },
  data() {
    return {};
  },

  computed: {
    resizeDebounce() {
      return _.debounce(() => {
        this.resizePainter();
      }, 100);
    },
    baseDrawDataObj() {
      return JSON.parse(this.initJson);
    },
    centerGraph() {
      // 延迟至少 650ms 给其他动画一些时间
      return _.debounce(this._centerGraph, 650);
    },
    nodeList() {
      return this.gConfig?.node?.nodeList ?? [];
    },
    startNodeType() {
      return this.gConfig?.node?.startNodeType ?? "START";
    },
  },
  watch: {
    // 启用停用
    qaTreeDisabled(value) {
      this.xGraph.setMode(value ? "custom" : "default");
    },
  },

  mounted() {
    this.init();
  },

  beforeUnmount() {
    console.log("beforeUnmount1");
    window.removeEventListener("resize", this.resizeDebounce);
    this.xGraph.destroy();
  },

  methods: {
    async init() {
      this.registerItems();
      this.registerBehavior();
      this.initGraph();
      this.registerEvent(this.xGraph);
      window.addEventListener("resize", this.resizeDebounce);
      this.draw();
      this.centerGraph();
    },

    async validateXGraph() {
      validateXGraph(this.xGraph, {
        illicitRingType: ["ReplyMessage"],
      });
    },
    async validateNode(node) {
      validateNode(node, this.xGraph);
    },

    async nodeRelationCheck(node) {
      nodeRelationCheck(node, this.xGraph);
    },
    handlerSave() {
      console.log(this.xGraph.save());
      this.validateXGraph();
      return this.xGraph.save();
    },
    async organizeLayout(isManual) {
      // const chatData = this.xGraph.save();
      // const { predictLayout, confidence } = await GraphLayoutPredict.predict(
      //   chatData
      // );
      this.xGraph.updateLayout({});
    },
    async handleClickLayout(isManual) {
      // 手动整理时才整理离散节点
      await this.organizeLayout(isManual);
      // 等上一个动画结束执行该动画
      this.centerGraph();
    },
    // 将图内容移动到中央位置
    _centerGraph() {
      this.xGraph.fitCenter(true, {
        duration: 500, // Number，一次动画的时长
        easing: "easeQuadInOut", // String，动画函数
      });
    },
    draw() {
      this.initData();
      this.xGraph.read({
        nodes: _.cloneDeep(this.graphNodes),
        edges: _.cloneDeep(this.graphEdges),
      });
    },

    initData() {
      this.initNodes();
      this.initEdges();
    },

    initNodes() {
      // 如果是空画布, 新增开始节点
      const nodes = this.baseDrawDataObj.nodes;
      this.graphNodes = nodes || [];
      if (this.graphNodes.length === 0) {
        const nodeType = this.startNodeType;
        const nodeOpt = this.nodeList.find((node) => node.type === nodeType);
        const nodeName = `${nodeOpt.name}${1}`;
        this.graphNodes = [
          {
            id: getNodeUUID(),
            type: "start-node",
            x: 0,
            y: 0,
            label: nodeName,
            nodeData: {
              nodeData: {},
              nodeName,
              nodeType,
            },
          },
        ];
      }
    },
    initEdges() {
      const edges = this.baseDrawDataObj.edges;
      this.graphEdges = edges || [];
    },
    registerItems() {
      const edgeTypes = [
        { name: "line" },
        { name: "polyline" },
        { name: "arc" },
        { name: "quadratic" },
        { name: "cubic" },
        { name: "cubic-vertical" },
        { name: "cubic-horizontal" },
        { name: "loop" },
      ];
      edgeTypes.forEach((opt) => {
        const { name } = opt;
        const config = getEdgeDefineCfg(name);

        G6.registerEdge(
          "custom:" + name,
          config.edgeDefinition,
          config.extendShapeType
        );
      });
      // console.log(this.gConfig);

      const styleMaps = _.chain(this.nodeList)
        .map((v) => {
          return [v.type, v.styles];
        })
        .fromPairs()
        .value();

      G6.registerNode(
        "custom-node",
        getCustomNodeCfg({
          styleMaps,
        }),
        "single-node"
      );

      G6.registerNode(
        "start-node",
        getStartNodeCfg({ styleMaps }),
        "single-node"
        // "rect"
      );
    },

    registerBehavior() {
      G6.registerBehavior(
        "delete-edge",
        getDeleteEdgeOpt({
          cfg: this.gConfig.edge.deleteEdgeBehavior,
        })
      );

      // node 的点击事件
      G6.registerBehavior("node-click", nodeClick);

      // 按钮的点击事件
      G6.registerBehavior("node-button-click", buttonClick);

      // 拖拽左侧 DOM 生成新 node
      G6.registerBehavior(
        "drag-create-node",
        getDragCreateNodeOpt({
          startNodeType: this.startNodeType,
          nodeList: this.nodeList,
          ...this.gConfig.node.dragCreateNodeBehavior,
        })
      );

      // 拖拽 node 末尾圆点生成 edge
      G6.registerBehavior(
        "drag-create-edge",
        getDragCreateEdgeOpt(this.gConfig.edge.createEdgeBehavior)
      );

      // 点击 node 末尾圆点生成 edge
      G6.registerBehavior(
        "click-create-edge",
        getClickCreateEdgeOpt(this.gConfig.edge.createEdgeBehavior)
      );
    },
    registerEvent(graph) {
      // 初次渲染
      graph.on("afterrender", () => {
        console.log("afterrender11");

        setTimeout(() => {
          try {
            const findNode = this.xGraph.find("node", (node) => {
              return node.get("type") === "start-node";
            });
            if (findNode) {
              this.xGraph.focusItem(findNode, true);
            }
            this.validateXGraph();
            // TODO: 查下这个设置有什么用
            // 查过了，没什么用，用来设置刷新策略，默认就是 true
            // https://github.com/antvis/G6/issues/2193
            // 实际上，所有的残留，都是自己设置错误导致的。
            // this.xGraph.get("canvas").set("localRefresh", true);
          } catch (error) {}
        }, 40);
      });

      graph.on("edge:mouseenter", ({ item }) => {
        // console.log("edge:mouseenter");
        graph.setItemState(item, "active", true);
      });
      graph.on("edge:mouseleave", ({ item }) => {
        graph.setItemState(item, "active", false);
      });
      graph.on("node:mouseenter", ({ item }) => {
        // active 表示 hover 状态
        graph.setItemState(item, "active", true);
      });
      graph.on("node:mouseleave", ({ item }) => {
        // active 表示 hover 状态
        graph.setItemState(item, "active", false);
      });

      graph.on("xNode:clickNode", (ev) => {
        this.editNode(ev);
      });

      graph.on("xNode:buttonClick", (ev) => {
        const { target, item } = ev;
        const targetName = target.get("name") || "";
        const buttonType = /button:(.+)/.exec(targetName)[1];
        console.log(buttonType);
        if (buttonType === "delete") {
          // 删除节点，要把节点的上下边都给删除
          this.deleteNode(ev);
        }
        if (buttonType === "copy") {
          this.copyNode(ev);
        }
        if (buttonType === "edit") {
          this.editNode(ev);
        }
      });

      graph.on("xEdge:addOrUpdateEnd", () => {
        console.log("xEdge:addOrUpdateEnd");
        this.validateXGraph();
      });
      graph.on("xEdge:updateEdgeCfg", ({ item }) => {
        console.log("xEdge:updateEdgeCfg");
        this.validateXGraph();
      });

      graph.on("xEdge:removeItem", () => {
        console.log("xEdge:removeItem");
        this.validateXGraph();
      });

      graph.on("dragCreateNode", (params) => {
        console.log(params);
        const newNode = this.createNode(
          params.nodeType,
          params.position,
          params.nodeData
        );
        // 新增完，不执行全部验证，只执行部分验证
        // this.validateXGraph();

        // 新增完，不执行节点验证
        this.validateNode(newNode);
      });

      graph.on("click", (e) => {
        console.log("canvas:click");
        if (!e.item) {
          this.closeAllDialog();
        }
      });
    },
    initGraph() {
      const qaTreeG6Dom = document.getElementById("qa-tree-g6");
      const painterHeight = parseInt(getComputedStyle(qaTreeG6Dom).height);
      const painterWidth = parseInt(getComputedStyle(qaTreeG6Dom).width);
      const plugins = [
        (() => {
          const minimapOpt = this.gConfig.minimap;
          if (minimapOpt === true) {
            return new G6.Minimap({
              container: "minimap",
              className: "minimap",
              type: "keyShape",
              size: [263, 136],
            });
          }
          if (minimapOpt) {
            return new G6.Minimap({
              container: "minimap",
              className: "minimap",
              ...minimapOpt,
            });
          }
        })(),
        (() => {
          const oldOnMenuShow = G6.Menu.prototype.onMenuShow;
          G6.Menu.prototype.onMenuShow = function (evt) {
            const newOnMenuShow = oldOnMenuShow.bind(this);
            if (evt?.item?.destroyed) {
              this.onMenuHide();
              return;
            } else {
              return newOnMenuShow(evt);
            }
          };

          return new G6.Menu({
            offsetX: 6,
            offsetY: 10,
            itemTypes: ["edge"],
            trigger: "click",
            getContent(e) {
              console.log(e);
              const edge = e.item;
              if (edge) {
                const edgeStartNodeData = edge.getSource().getModel().nodeData;
                const relationList = edgeStartNodeData.relationList;

                const outDiv = document.createElement("div");
                outDiv.style.width = "180px";
                outDiv.innerHTML =
                  "<ul>" +
                  relationList
                    .map((v) => {
                      return `<li data-edge-relation-id="${
                        v.id
                      }" data-edge-relation-name="${v.name}">${
                        v.name || "&nbsp;"
                      }</li>`;
                    })
                    .join("") +
                  "</ul>";

                return outDiv;
              }
            },
            handleMenuClick: (target, item) => {
              const edgeRelationName =
                target.getAttribute("data-edge-relation-name") || "";
              const edgeRelationId = target.getAttribute(
                "data-edge-relation-id"
              );
              if (!item.destroyed && edgeRelationId) {
                item.update({
                  label: edgeRelationName + " ▼",
                  edgeData: {
                    relationId: edgeRelationId,
                  },
                });
                this.xGraph.emit("xEdge:updateEdgeCfg", { item });
              }
            },
            shouldBegin(e) {
              const item = e.target;
              if (!e.item.destroyed) {
                if (
                  (item.get("name") === "text-shape" &&
                    item.get("className") === "edge-label") ||
                  item.get("name") === "text-bg-shape"
                ) {
                  const edge = e.item;
                  const edgeStartNodeData = edge
                    .getSource()
                    .getModel().nodeData;
                  if (
                    edgeStartNodeData.relationList &&
                    edgeStartNodeData.relationList.length
                  ) {
                    return true;
                  }
                }
              }
            },
          });
        })(),
        (() => {
          const tooltip = new G6.Tooltip({
            offsetX: 6,
            offsetY: 10,
            getContent(e) {
              const node = e.item;
              const errorData = node.getModel().errorData || [];

              const outDiv = document.createElement("div");
              // outDiv.style.width = "180px";
              outDiv.innerHTML =
                "<ul>" +
                errorData
                  .map((v) => {
                    return `<li>${v.value || "&nbsp;"}</li>`;
                  })
                  .join("") +
                "</ul>";
              return outDiv;
            },
            itemTypes: ["node"],
            trigger: "mouseenter",
            shouldBegin(e) {
              const item = e.target;
              if (!e.item.destroyed) {
                if (item.get("name") === "error-icon") {
                  const errorData = e.item.getModel().errorData || [];
                  if (errorData.length > 0) {
                    return true;
                  }
                }
              }
            },
          });
          return tooltip;
        })(),
      ].filter((v) => v);

      const cfg = _.merge(
        {},
        g6Config,
        {
          container: "qa-tree-g6",
          width: painterWidth,
          defaultEdge: {
            type: "custom:" + g6Config.defaultEdge.type,
          },
          height: painterHeight,
          plugins,
        },
        this.gConfig.g6Config
      );

      this.xGraph = new G6.Graph(cfg);
      // 初始化数量
      this.xGraph.nodeNum = {};
    },
    async resizePainter() {
      const painterHeight = parseInt(
        getComputedStyle(this.$refs.painter).height
      );
      const painterWidth = parseInt(getComputedStyle(this.$refs.painter).width);
      this.xGraph.changeSize(painterWidth, painterHeight);
      this.xGraph.zoomTo(1, false, false);
      // 给上面动画一些时间
      await new Promise((resolve) => {
        setTimeout(() => {
          resolve(1);
        }, 650);
      });
      this.centerGraph();
    },

    // edge 的终点更新
    afterUpdateEdge({ item }) {
      // 拿到 edge 的 起点，开始验证它有几条 edge
      // 添加连线后整理画布
      // this.handleClickLayout();
    },

    deleteNode(ev) {
      const { item } = ev;
      const edges = item.getEdges();
      edges.forEach((edge) => {
        this.xGraph.removeItem(edge);
      });
      const edgesLength = edges.length;
      this.xGraph.removeItem(item);
      // DESC: 性能优化
      // 如果有连线，则进行全图验证。否则可以跳过
      if (edgesLength > 0) {
        this.validateXGraph();
      }
    },

    async copyNode(ev) {
      const { item } = ev;
      const model = item.getModel();
      const r = 150;
      const angle = [-60, 60];
      const arc = _.random(
        _.toInteger(-angle[0] * Math.PI),
        _.toInteger(-angle[1] * Math.PI)
      );
      const dx = r * Math.cos(arc / 180);
      const dy = r * Math.sin(arc / 180);
      await Promise.resolve(1);
      this.createNode(
        model.nodeData.nodeType,
        {
          x: model.x + dx,
          y: model.y + dy,
        },
        model.nodeData
      );
    },

    createNode(nodeType, position, nodeData) {
      const num =
        this.xGraph.findAll("node", (node) => {
          return _.get(node.getModel(), "nodeData.nodeType") === nodeType;
        })?.length ?? 0;
      const nodeOpt = this.nodeList.find((node) => node.type === nodeType);

      const nodeName = `${nodeOpt.name}${num + 1}`;
      const node = this.xGraph.addItem("node", {
        id: getNodeUUID(),
        type: nodeType === this.startNodeType ? "start-node" : "custom-node",
        x: position.x,
        y: position.y,
        label: nodeName,
        nodeData: {
          ...nodeData,
          nodeName,
          nodeType,
        },
      });
      node.toFront();
      return node;
    },

    highLightNodeEdges({ item }) {
      this.cancelHighLightAllEdges();

      const edges = item.getEdges();
      edges.forEach((edge) => this.xGraph.setItemState(edge, "running", true));
    },
    cancelHighLightAllEdges() {
      this.xGraph.stopAnimate();
      const edges = this.xGraph.getEdges();
      edges.forEach((edge) => this.xGraph.setItemState(edge, "running", false));
    },
    highLightNodePathEdges({ item }) {
      this.cancelHighLightAllEdges();
      let allEdges = [];
      let allNodes = [];
      let nodes = [item];
      let edgesArr = [];
      for (let i = 0; i < 20; i++) {
        for (let node of nodes) {
          // if (allNodes.includes(node)) continue;
          allNodes.push(node);
          const cEdges = node.getInEdges();
          edgesArr.push(cEdges);
        }
        nodes = [];
        for (let edges of edgesArr) {
          for (let edge of edges) {
            if (allEdges.includes(edge)) continue;
            allEdges.push(edge);
            nodes.push(edge.getSource());
          }
        }
        edgesArr = [];
      }

      allEdges.forEach((edge) =>
        this.xGraph.setItemState(edge, "running", true)
      );
    },
    toggleEdgeType() {
      const edgeTypes = [
        "line",
        "polyline",
        "arc",
        "quadratic",
        "cubic",
        "cubic-vertical",
        "cubic-horizontal",
        "loop",
      ];
      const currentEdgeType = this.graphEdges[0]?.type.match();
      const allData = this.xGraph.save();
      const currentEdgeType1 = allData.edges[0].type.match(/custom:(.+)/)[1];
      const nextType =
        edgeTypes[
          (edgeTypes.findIndex((v) => v === currentEdgeType1) + 1) %
            edgeTypes.length
        ];

      this.xGraph.read({
        ...allData,
        edges: allData.edges.map((v) => {
          return {
            ...v,
            type: "custom:" + nextType,
          };
        }),
      });
      console.log(currentEdgeType, currentEdgeType1, nextType);
    },
    editNode(ev) {
      const node = ev.item;
      this.$refs.editNode.open(node.getModel());
    },
    closeAllDialog() {
      this.$refs.editNode.close();
    },
    handlerEditNodeDialogClose(newModelOpt) {
      const id = newModelOpt.id;
      const node = this.xGraph.findById(id);
      this.nodeRelationCheck(node);
      // 如果编辑的节点有连线，则执行全部图形验证
      if (node.getEdges().length > 0) {
        this.validateXGraph();
      } else {
        this.validateNode(node);
      }
    },
    // 提交编辑 node 的命令
    handlerEditNodeSubmit(newModelOpt) {
      const id = newModelOpt.id;
      const node = this.xGraph.findById(id);
      node.update(newModelOpt);
      const sourceOutEdges = node.getOutEdges();
      const relationList = _.get(newModelOpt, "nodeData.relationList", []);

      let needValidateAllGraph = false;
      // 编辑出点 edge 的数据
      sourceOutEdges.forEach((edge) => {
        const edgeModel = edge.getModel();
        const relationId = edgeModel?.edgeData?.relationId;
        if (relationId) {
          const newRelationOpt = relationList.find((v) => v.id === relationId);
          if (newRelationOpt && newRelationOpt.id) {
            edge.update({
              label: newRelationOpt.name + " ▼",
              edgeData: {
                relationId: newRelationOpt.id,
              },
            });
          } else {
            this.xGraph.removeItem(edge);
            needValidateAllGraph = true;
          }
        }
      });

      if (needValidateAllGraph) {
        this.validateXGraph();
      }
      // this.$refs.editNode.close();
    },
  },
};
</script>

<style lang="less" scoped>
