type Node = {
  id?: string;
  type?: string;
};
type Edge = {
  id?: string;
  source?: string;
  target?: string;
};

const findArrayIndex = (arr: any[], item: any) => {
  const r: number[] = [];
  for (let i = 0; i < arr.length; i++) {
    if (arr[i] === item) {
      r.push(i);
    }
  }
  return r;
};

export const findRing = (data: {
  nodes?: Array<Node>;
  edges?: Array<Edge>;
}) => {
  const nodes = data.nodes || [];
  const edges = data.edges || [];
  const nodePath: Node[] = [];
  const edgePath: Edge[] = [];

  const result: Array<{
    nodes: Node[];
    edges: Edge[];
  }> = [];

  const o = nodes[0];
  nodePath.push(o);

  let c = o;
  const cEdges = edges.filter((v) => v.source === c.id);
  const nextNAndE = cEdges.map((v) => {
    return {
      node: nodes.find((n) => n.id === v.target),
      edge: v,
    };
  });

  const helper = (
    nextNAndE: Array<{
      node?: Node;
      edge: Edge;
    }>
  ) => {
    for (let i = 0; i < nextNAndE.length; i++) {
      const { node, edge } = nextNAndE[i];
      if (node) {
        const si = findArrayIndex(nodePath, node);
        if (si.length > 0) {
          si.forEach((i) => {
            result.push({
              nodes: [...nodePath.slice(i), node],
              edges: [...edgePath.slice(i), edge],
            });
          });
        } else {
          c = node;
          nodePath.push(c);
          edgePath.push(edge);
          const cEdges = edges.filter((v) => v.source === c.id);
          const newNextNAndE = cEdges.map((v) => {
            return {
              node: nodes.find((n) => n.id === v.target),
              edge: v,
            };
          });

          helper(newNextNAndE);
          nodePath.pop();
          edgePath.pop();
        }
      }
    }
  };
  helper(nextNAndE);
  return result;
};
