<template>
  <t-drawer
    v-model:visible="visible"
    :footer="false"
    size="medium"
    class="edit-node-compo"
    prevent-scroll-through
    :header="modelData.nodeData.nodeName"
    :show-overlay="true"
    @close="handlerClose"
  >
    <!-- <div>
      {{ modelData }}
    </div> -->
    <t-form
      ref="formValidatorStatus"
      :data="formData"
      :label-width="80"
      :status-icon="true"
      @reset="onReset"
    >
      <div
        v-for="(item, index) in formData.relationList"
        :key="item.id"
        style="padding: 0px 24px 30px 0"
      >
        <t-form-item
          label="条件组"
          :name="`relationList[${index}].name`"
          :rules="[
            {
              required: true,
              message: '不能为空',
              trigger: 'blur',
            },
          ]"
        >
          <t-space>
            <t-input v-model="formData.relationList[index].name"></t-input>
            <t-button
              theme="default"
              :disabled="formData.relationList.length <= 1"
              @click="deleteStudent(index)"
            >
              删除
            </t-button>
          </t-space>
        </t-form-item>
      </div>
      <t-form-item :status-icon="false">
        <t-space size="small">
          <t-button theme="default" @click="addStudent">添加规则</t-button>
        </t-space>
      </t-form-item>
      <!-- <t-form-item :status-icon="false">
        <t-space size="small">
          <t-button theme="primary" type="submit">提交</t-button>
        </t-space>
      </t-form-item> -->
    </t-form>
  </t-drawer>
</template>

<script lang="ts" setup>
import { nextTick, reactive, ref, toValue, watch } from "vue";
import { FormInstanceFunctions, MessagePlugin } from "tdesign-vue-next";
import _ from "lodash";
import { getRelationUUID } from "@/utils";
const emit = defineEmits(["submit", "close"]);

type Model = {
  id: string;
  label: string;
  nodeData: {
    nodeName: string;
    nodeType: string;
    relationList: Array<{ name: string; id: string }>;
  };
  type: string;
  x: number;
  y: number;
};

const formValidatorStatus = ref<FormInstanceFunctions>(null as any);
const visible = ref(false);

const modelData = ref<Model>({
  id: "",
  label: "",
  nodeData: {
    nodeName: "",
    nodeType: "",
    relationList: [],
  },
  type: "",
  x: 0,
  y: 0,
});

const open = async (cfg: Model) => {
  visible.value = true;

  modelData.value = cfg;
  formData.relationList = cfg.nodeData.relationList || [];

  await nextTick();
  formValidatorStatus.value.validate();
};

const close = () => {
  visible.value = false;
};

const formData = reactive<{
  relationList: Model["nodeData"]["relationList"];
}>({
  relationList: [],
});

const addStudent = () => {
  formData.relationList.push({
    id: getRelationUUID(),
    name: "",
  });
};
const deleteStudent = (index: number) => {
  formData.relationList.splice(index, 1);
};

// const rules = {
//   fail: [{ required: true, message: "必填", type: "error" }],
//   password: [{ required: true, message: "必填", type: "warning" }],
// };

const onReset = () => {
  MessagePlugin.success("重置成功");
};

const submitForm = () => {
  emit(
    "submit",
    _.mergeWith(
      {},
      _.cloneDeep(modelData.value),
      {
        nodeData: _.cloneDeep(formData),
      },
      (source, target) => {
        if (_.isArray(source)) {
          return target;
        }
      }
    )
  );
};

watch(formData, (newVal, oldVal) => {
  submitForm();
});

const handlerClose = () => {
  emit(
    "close",
    _.mergeWith(
      {},
      _.cloneDeep(modelData.value),
      {
        nodeData: _.cloneDeep(formData),
      },
      (source, target) => {
        if (_.isArray(source)) {
          return target;
        }
      }
    )
  );
};
// const onSubmit = (ev: any) => {
//   console.log(ev);
//   const { validateResult, firstError } = ev;
//   if (validateResult === true) {
//     MessagePlugin.success("提交成功");
//     emit(
//       "submit",
//       _.merge({}, _.cloneDeep(modelData.value), {
//         nodeData: _.cloneDeep(formData),
//       })
//     );
//   } else {
//     console.log("Validate Errors: ", firstError, validateResult);
//     MessagePlugin.warning(firstError);
//   }
// };

defineExpose({
  open,
  close,
});
</script>
